<?php
declare(strict_types=1);
namespace BYPCMS\Core;

final class Journal {
    public static function menu(array $items,string $parent='',int $depth=0):string {
        if($depth>3)return '';$out='';foreach($items as $i=>$m){if(($m['parent']??'')!==$parent)continue;$id=$m['id']??'item-'.$i;$label=Content::e($m['label']??'');$url=Content::e(Content::url($m['url']??''));$child=self::menu($items,$id,$depth+1);$out.=$child?'<details class="j-menu-group"><summary>'.$label.'</summary><div><a href="'.$url.'">Обзор: '.$label.'</a>'.$child.'</div></details>':'<a href="'.$url.'">'.$label.'</a>';}return $out;
    }
    public static function render(array $pages,array $terms,array $settings,string $path,string $base='',bool $preview=false,string $snapshot=''): void {
        $e=[Content::class,'e'];$imageUrl=static fn($p)=>Content::asset(Content::imageUrl((string)$p));$path=trim($path,'/');$query=$_GET;$href=static function(string $p,array $q=[])use($base,$snapshot){if($snapshot)$q['snapshot']=$snapshot;return $base.$p.($q?'?'.http_build_query($q):'');};
        $cats=array_values(array_filter($terms,fn($t)=>$t['kind']==='category'));$authors=array_values(array_filter($terms,fn($t)=>$t['kind']==='author'));$termName=static function(string $slug,string $kind)use($terms){foreach($terms as $t)if($t['slug']===$slug&&$t['kind']===$kind)return $t['title'];return '';};
        $articles=array_values(array_filter($pages,fn($p)=>($p['kind']??'page')==='article'));$title=$settings['site_name']??'Journal';$description=$settings['tagline']??'Архитектура. Люди. Пространство.';$page=null;$term=null;$mode='home';$status=200;$list=$articles;
        if($path==='articles')$mode='listing';elseif($path==='search'){$mode='search';$title='Поиск';$q=mb_substr(trim((string)($query['q']??'')),0,100);$list=array_values(array_filter($articles,fn($p)=>$q!==''&&(isset($settings['_search_matches'])?in_array((int)$p['id'],$settings['_search_matches'],true):mb_stripos($p['title'].' '.$p['excerpt'].' '.strip_tags($p['content']),$q)!==false)));}
        elseif(preg_match('#^(category|author)/([a-z0-9-]+)$#D',$path,$m)){$mode=$m[1];foreach($terms as $t)if($t['kind']===$m[1]&&$t['slug']===$m[2])$term=$t;if(!$term)$mode='404';else{$title=$term['title'];$description=$term['description'];$list=array_values(array_filter($articles,fn($p)=>($p[$m[1]]??'')===$m[2]));}}
        elseif($path!==''){foreach($pages as $p)if(trim($p['slug'],'/')===$path)$page=$p;$mode=$page?(($page['kind']??'page')==='article'?'article':'page'):'404';if($page){$title=($page['seo_title']??'')?:$page['title'];$description=($page['seo_description']??'')?:$page['excerpt'];}}
        if($mode==='search')usort($list,static fn($a,$b)=>(int)(mb_stripos($b['title'],$q)!==false)<=>(int)(mb_stripos($a['title'],$q)!==false));if($mode==='listing')$title='Все истории';if($mode==='404'){$status=404;$title='Страница не найдена';$description='Эта история пока не найдена. Попробуйте поиск или вернитесь на главную.';}
        http_response_code($status);header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: default-src \'self\'; img-src \'self\' https: data:; style-src \'self\' \'unsafe-inline\'; font-src \'self\'; script-src \'self\'; frame-ancestors \'self\'; base-uri \'none\'; form-action \'self\'');
        if($preview){header('X-Robots-Tag: noindex, nofollow, noarchive');header('Cache-Control: no-store');}
        $logo=Content::imageUrl($settings['logo']??'');$bodyFont=($settings['font']??'')==='system'?'system-ui,Arial,sans-serif':'JournalSans,Arial,sans-serif';$headingFont=($settings['heading_font']??'')==='georgia'?'Georgia,serif':'JournalDisplay,Georgia,serif';
        $siteUrl=rtrim(Content::url($settings['site_url']??''),'/');$canonical=Content::url($page['canonical']??'')?:$siteUrl.$base.'/'.($path?$path.'/':'');if(str_starts_with($canonical,'/'))$canonical=$siteUrl.$canonical;$image=$page['cover']??($articles[0]['cover']??'');$accent=preg_match('/^#[0-9a-f]{6}$/i',$settings['accent']??'')?$settings['accent']:'#b7472f';
        $toc=[];$reading='';if($page){$reading=Content::html($page['content']??'').Content::blocks($page['blocks']??[]);$reading=preg_replace_callback('#<h([23])(?: [^>]*)?>(.*?)</h\1>#su',static function($m)use(&$toc){$id='story-section-'.(count($toc)+1);$toc[]=['id'=>$id,'title'=>strip_tags(html_entity_decode($m[2],ENT_QUOTES,'UTF-8'))];return '<h'.$m[1].' id="'.$id.'">'.$m[2].'</h'.$m[1].'>';},$reading);}
        $card=static function(array $p,string $class='')use($e,$href,$termName,$imageUrl){$url=$href('/'.trim($p['slug'],'/').'/');echo '<article class="j-card '.$e($class).'"><a class="j-image" href="'.$e($url).'">';if(!empty($p['cover'])&&Content::imageUrl($p['cover']))echo '<img src="'.$e($imageUrl($p['cover'])).'"'.Content::imageSet($p['cover']).' alt="'.$e($p['cover_alt']??$p['title']).'" width="1000" height="750" loading="lazy">';else echo '<span class="j-noimage">J.</span>';echo '</a><div class="j-card-copy"><span class="j-eyebrow">'.$e($termName($p['category']??'','category')).'</span><h2><a href="'.$e($url).'">'.$e($p['title']).'</a></h2><p>'.$e($p['excerpt']).'</p><small>'.$e($termName($p['author']??'','author')?:'Редакция').' <span>·</span> '.$e(self::date($p['published_at']??'')).'</small></div></article>';};
        ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title) ?><?= $mode==='home'?'':' — '.$e($settings['site_name']??'Journal') ?></title><meta name="description" content="<?= $e($description) ?>"><meta name="robots" content="<?= $preview||!empty($page['noindex'])||in_array($mode,['search','404'],true)?'noindex,follow':'index,follow' ?>"><link rel="canonical" href="<?= $e($canonical) ?>"><meta property="og:type" content="<?= $mode==='article'?'article':'website' ?>"><meta property="og:title" content="<?= $e($title) ?>"><meta property="og:description" content="<?= $e($description) ?>"><meta property="og:url" content="<?= $e($canonical) ?>"><?php if($image): ?><meta property="og:image" content="<?= $e(str_starts_with($image,'/')?$siteUrl.$image:$image) ?>"><?php endif ?><link rel="stylesheet" href="<?= $e(Content::asset('/themes/journal/journal.css')) ?>?v=1.0.0"><link rel="icon" href="<?= $e(Content::asset('/themes/journal/favicon.svg')) ?>"><style>:root{--accent:<?= $e($accent) ?>;--j-body:<?= $e($bodyFont) ?>;--j-heading:<?= $e($headingFont) ?>}</style></head><body class="j-site"><a class="j-skip" href="#main">К содержанию</a>
        <?php if($preview&&$base===''): ?><div class="j-preview-bar">Предпросмотр · изменения не опубликованы <a id="preview-close" href="/manage/?section=<?= ($page['kind']??'article')==='page'?'pages':'articles' ?>&amp;editor=<?= !empty($page['id'])&&$page['id']>0?(int)$page['id']:'new' ?>">Вернуться к редактированию ×</a></div><script src="<?= $e(Content::asset('/themes/journal/preview.js')) ?>" defer></script><?php endif ?><header class="j-header"><div class="j-topline"><span>Независимый журнал о пространстве</span><span>Архитектура / Дизайн / Культура</span></div><div class="j-masthead"><a href="<?= $e($href('/')) ?>" class="j-logo"><?php if($logo): ?><img src="<?= $e(Content::asset($logo)) ?>" alt="<?= $e($settings['site_name']??'Journal') ?>"><?php else: ?><?= $e($settings['site_name']??'Journal') ?><span>•</span><?php endif ?></a><p><?= $e($settings['tagline']??'Архитектура. Люди. Пространство.') ?></p><a class="j-search-link" href="<?= $e($href('/search/')) ?>" aria-label="Поиск по журналу">Поиск <span aria-hidden="true">↗</span></a></div><nav class="j-nav" aria-label="Основное меню"><a href="<?= $e($href('/articles/')) ?>">Все истории</a><?php foreach($cats as $t): ?><a href="<?= $e($href('/category/'.$t['slug'].'/')) ?>"><?= $e($t['title']) ?></a><?php endforeach ?><?php if(!empty($settings['menu'])): echo self::menu($settings['menu']); else: ?><a href="<?= $e($href('/about/')) ?>">О журнале</a><a href="<?= $e($href('/contacts/')) ?>">Контакты</a><?php endif ?></nav></header>
        <main id="main" class="j-main">
        <?php if($mode==='home'): $featured=array_values(array_filter($articles,fn($p)=>!empty($p['featured'])));$lead=$featured[0]??$articles[0]??null; ?>
          <div class="j-section-line"><span>В фокусе</span><span>Пространство для нового взгляда</span></div>
          <?php if($lead): ?><section class="j-lead"><div class="j-lead-copy"><span class="j-eyebrow"><?= $e($termName($lead['category']??'','category')) ?> <span>—</span> Выбор редакции</span><h1><a href="<?= $e($href('/'.$lead['slug'].'/')) ?>"><?= $e($lead['title']) ?></a></h1><p><?= $e($lead['excerpt']) ?></p><a class="j-read" href="<?= $e($href('/'.$lead['slug'].'/')) ?>">Читать историю <span>↗</span></a><small><?= $e($termName($lead['author']??'','author')) ?> · <?= $e(self::date($lead['published_at'])) ?></small></div><a class="j-lead-image" href="<?= $e($href('/'.$lead['slug'].'/')) ?>"><?php if(!empty($lead['cover'])): ?><img src="<?= $e($imageUrl($lead['cover'])) ?>"<?= Content::imageSet($lead['cover']) ?> alt="<?= $e($lead['cover_alt']??$lead['title']) ?>" width="1200" height="1100" fetchpriority="high"><?php endif ?><span>01 / История дня</span></a></section><?php else: ?><section class="j-empty"><h1>У каждой истории есть начало</h1><p>Новые материалы скоро появятся здесь.</p></section><?php endif ?>
          <section class="j-latest"><div class="j-section-line"><h2>Последние истории</h2><a href="<?= $e($href('/articles/')) ?>">Смотреть все ↗</a></div><div class="j-grid"><?php foreach(array_slice(array_values(array_filter($articles,fn($p)=>$p['id']!==($lead['id']??0))),0,6)as $i=>$p)$card($p,$i===0?'j-card-wide':''); ?></div></section>
          <section class="j-manifesto"><span class="j-eyebrow">Наш взгляд</span><h2>Замечать больше.<br><em>Чувствовать глубже.</em></h2><p>Истории о местах, предметах и людях, которые делают повседневную жизнь осмысленнее.</p><a href="<?= $e($href('/about/')) ?>">О журнале <span>↗</span></a></section>
        <?php elseif(in_array($mode,['listing','category','author','search'],true)):
          $sort=($query['sort']??'new')==='old'?'old':'new';if($sort==='old')$list=array_reverse($list);$pageNum=max(1,(int)($query['page']??1));$total=count($list);$pageCount=max(1,(int)ceil($total/6));$pageNum=min($pageNum,$pageCount);
          ?><div class="j-breadcrumb"><a href="<?= $e($href('/')) ?>">Главная</a><span>/</span><?= $e($title) ?></div><section class="j-list-heading"><span class="j-eyebrow"><?= $mode==='author'?'Автор журнала':($mode==='category'?'Рубрика':'Journal / Истории') ?></span><?php if(!empty($term['image'])): ?><img class="j-term-image <?= $mode==='category'?'j-category-cover':'' ?>" src="<?= $e(Content::url($term['image'])) ?>"<?= Content::imageSet($term['image'],$mode==='author'?'120px':'100vw') ?> alt="<?= $e($term['title']) ?>" width="120" height="120"><?php endif ?><h1><?= $e($title) ?></h1><?php if($term): ?><p><?= $e($description) ?></p><?php endif ?>
          <?php if($mode==='search'): ?><form class="j-search-form" method="get" action="<?= $e($base.'/search/') ?>"><?php if($snapshot): ?><input type="hidden" name="snapshot" value="<?= $e($snapshot) ?>"><?php endif ?><label for="q">Что вас интересует?</label><div><input id="q" name="q" value="<?= $e($q) ?>" placeholder="Например, свет или город" maxlength="100"><button>Найти ↗</button></div></form><?php else: ?><form method="get" class="j-sort"><?php if($snapshot): ?><input type="hidden" name="snapshot" value="<?= $e($snapshot) ?>"><?php endif ?><label>Порядок <select name="sort"><option value="new">Сначала новые</option><option value="old" <?= $sort==='old'?'selected':'' ?>>Сначала ранние</option></select></label><button>Применить</button></form><?php endif ?></section>
          <div class="j-section-line"><span><?= $total ?> историй</span><span>Страница <?= $pageNum ?> / <?= $pageCount ?></span></div><?php if(!$total): ?><div class="j-empty"><h2><?= $mode==='search'?'Пока ничего не найдено':'Здесь скоро появятся истории' ?></h2><p>Попробуйте другой запрос или посмотрите все публикации.</p><a href="<?= $e($href('/articles/')) ?>">Все истории ↗</a></div><?php else: ?><div class="j-grid j-list-grid"><?php foreach(array_slice($list,($pageNum-1)*6,6)as $p)$card($p); ?></div><nav class="j-pagination" aria-label="Страницы результатов"><?php for($i=1;$i<=$pageCount;$i++): ?><a <?= $i===$pageNum?'aria-current="page"':'' ?> href="<?= $e($href('/'.$path.'/',array_filter(['page'=>$i,'sort'=>$sort,'q'=>$query['q']??null]))) ?>"><?= $i ?></a><?php endfor ?></nav><?php endif ?>
        <?php elseif(in_array($mode,['article','page'],true)): ?>
          <div class="j-breadcrumb"><a href="<?= $e($href('/')) ?>">Главная</a><span>/</span><?php $parentId=(int)($page['parent_id']??0);$ancestors=[];for($level=0;$level<20&&$parentId;$level++){$parent=null;foreach($pages as $candidate)if((int)$candidate['id']===$parentId){$parent=$candidate;break;}if(!$parent)break;array_unshift($ancestors,$parent);$parentId=(int)($parent['parent_id']??0);}foreach($ancestors as $ancestor): ?><a href="<?= $e($href('/'.$ancestor['slug'].'/')) ?>"><?= $e($ancestor['title']) ?></a><span>/</span><?php endforeach ?><?php if(!empty($page['category'])): ?><a href="<?= $e($href('/category/'.$page['category'].'/')) ?>"><?= $e($termName($page['category'],'category')) ?></a><?php else: ?>Журнал<?php endif ?></div><article class="j-story"><header><span class="j-eyebrow"><?= $mode==='article'?'История / '.$e($termName($page['category']??'','category')):'Journal' ?></span><h1><?= $e($page['title']) ?></h1><p class="j-deck"><?= $e($page['excerpt']) ?></p><?php if($mode==='article'): ?><div class="j-byline"><?php if($termName($page['author']??'','author')): ?><a href="<?= $e($href('/author/'.(($page['author']??'')?:'journal').'/')) ?>"><?= $e($termName($page['author']??'','author')?:'Редакция') ?></a><?php else: ?><span>Редакция</span><?php endif ?><span><?= $e(self::date($page['published_at']??'')) ?></span><span><?= max(1,(int)ceil(mb_strlen(strip_tags($page['content']??''))/1100)) ?> мин чтения</span></div><?php endif ?></header><?php if(!empty($page['cover'])): ?><figure class="j-story-cover"><img src="<?= $e($imageUrl($page['cover'])) ?>"<?= Content::imageSet($page['cover']) ?> alt="<?= $e($page['cover_alt']??'') ?>" width="1600" height="1000"></figure><?php endif ?>
          <div class="j-reading"><aside><span class="j-eyebrow">В этой истории</span><?php if($toc): foreach($toc as $item): ?><a href="#<?= $e($item['id']) ?>"><?= $e($item['title']) ?></a><?php endforeach; else: ?><a href="#story-body">Читать материал ↓</a><?php endif ?><a href="<?= $e($href('/articles/')) ?>">Другие истории ↗</a></aside><div id="story-body" class="j-prose"><?= $reading ?><?php if(($page['slug']??'')==='contacts'): if(!empty($settings['email'])): ?><p><a href="mailto:<?= $e($settings['email']) ?>"><?= $e($settings['email']) ?></a></p><?php endif; if(!empty($settings['phone'])): ?><p><a href="tel:<?= $e(preg_replace('/[^+0-9]/','',$settings['phone'])) ?>"><?= $e($settings['phone']) ?></a></p><?php endif; endif ?></div></div></article>
          <?php if($mode==='article'): ?><section class="j-related"><div class="j-section-line"><h2>Продолжить чтение</h2><a href="<?= $e($href('/articles/')) ?>">Все истории ↗</a></div><div class="j-grid"><?php foreach(array_slice(array_values(array_filter($articles,fn($p)=>$p['id']!==$page['id'])),0,3)as $p)$card($p); ?></div></section><?php endif ?>
        <?php else: ?><section class="j-empty"><span class="j-eyebrow">404 / Потерянная страница</span><h1>Иногда стоит<br><em>сменить направление.</em></h1><p><?= $e($description) ?></p><a class="j-button" href="<?= $e($href('/search/')) ?>">Найти историю ↗</a></section><?php endif ?>
        </main><footer class="j-footer"><div><a class="j-logo" href="<?= $e($href('/')) ?>"><?php if($logo): ?><img src="<?= $e(Content::asset($logo)) ?>" alt="<?= $e($settings['site_name']??'Journal') ?>"><?php else: ?><?= $e($settings['site_name']??'Journal') ?><span>•</span><?php endif ?></a><p><?= $e($settings['tagline']??'') ?></p></div><nav aria-label="Меню в подвале"><?php if(!empty($settings['footer_menu'])): echo self::menu($settings['footer_menu']); else: ?><a href="<?= $e($href('/articles/')) ?>">Все истории</a><a href="<?= $e($href('/about/')) ?>">О журнале</a><a href="<?= $e($href('/contacts/')) ?>">Контакты</a><?php endif ?></nav><small>© <?= gmdate('Y') ?> · Независимый взгляд<br>Работает на BYPCMS Content</small></footer></body></html><?php
    }
    public static function date(string $date):string {if(!$date)return 'Без даты';$t=strtotime($date.' UTC');$months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];return gmdate('j',$t).' '.$months[(int)gmdate('n',$t)-1].' '.gmdate('Y',$t);}
}
